/**
 * ReviewSession — the command-side model of the 要確認 workspace (UI-050,
 * GUI_UX_SPEC §12/§14).
 *
 * All review interactions are recorded as `ReviewEdit`s: a status decision
 * (accept / dismiss / reopen) plus any note corrections (pitch shift,
 * delete/restore) the action produced. Each edit is pushed onto an undo
 * stack; undo/redo replay the inverse/forward values through the document
 * port, so decisions and corrections persist in the document model
 * (revision-bound — a new `scoreRevision` builds a new document and a new
 * session, so stale decisions are never carried across revisions, matching
 * the domain/review.py contract).
 *
 * The class is pure TypeScript — no React, no DOM — so the whole review
 * flow (including the keyboard-only acceptance path) is unit-testable.
 */
import type { ScoreDocumentPort } from "./document";
import { openIssues, type ReviewIssueStatus, type ScoreReviewIssue } from "./review";
import { NO_NOTE_EDIT, type ScoreNoteEdit } from "./scoreEdits";

/** One canonical note's before/after edit inside a ReviewEdit. */
export interface ReviewNoteChange {
  readonly canonicalId: string;
  readonly prev: ScoreNoteEdit;
  readonly next: ScoreNoteEdit;
}

/** A recorded review action - the undo/redo unit (§14 "review decision"). */
export interface ReviewEdit {
  /** Issue this edit is bound to; null for a direct note edit made
   *  outside the review workspace (#114 - the undo stack is shared). */
  readonly issueId: string | null;
  readonly prevStatus: ReviewIssueStatus | null;
  readonly nextStatus: ReviewIssueStatus | null;
  /** Note corrections applied alongside the status change (empty for a
   *  pure decision like 問題なし). */
  readonly noteChanges: readonly ReviewNoteChange[];
}

function editOf(doc: ScoreDocumentPort, canonicalId: string): ScoreNoteEdit {
  return doc.noteEdits().get(canonicalId) ?? NO_NOTE_EDIT;
}

export class ReviewSession {
  private readonly undoStack: ReviewEdit[] = [];
  private readonly redoStack: ReviewEdit[] = [];

  constructor(private readonly doc: ScoreDocumentPort) {}

  /** The revision these decisions are bound to. */
  get scoreRevision(): string {
    return this.doc.revisionId;
  }

  /** All issues with decisions applied (any status). */
  issues(): readonly ScoreReviewIssue[] {
    return this.doc.reviewIssues();
  }

  /** Issues still needing attention. */
  openIssues(): readonly ScoreReviewIssue[] {
    return openIssues(this.doc.reviewIssues());
  }

  pendingCount(): number {
    return this.openIssues().length;
  }

  statusOf(issueId: string): ReviewIssueStatus | null {
    return (
      this.doc.reviewIssues().find((i) => i.id === issueId)?.status ?? null
    );
  }

  noteEditOf(canonicalId: string): ScoreNoteEdit {
    return editOf(this.doc, canonicalId);
  }

  isDeleted(canonicalId: string): boolean {
    return editOf(this.doc, canonicalId).deleted;
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  /**
   * Record a pure decision (accepted / dismissed / back to open).
   * Returns null when the issue is unknown or already in that status —
   * callers treat that as a no-op, not an error.
   */
  decide(issueId: string, status: ReviewIssueStatus): ReviewEdit | null {
    const issue = this.doc.reviewIssues().find((i) => i.id === issueId);
    if (!issue || issue.status === status) return null;
    const edit: ReviewEdit = {
      issueId,
      prevStatus: issue.status,
      nextStatus: status,
      noteChanges: [],
    };
    this.doc.recordReviewDecision(issueId, status);
    this.push(edit);
    return edit;
  }

  /**
   * 音高修正: shift every canonical note of the issue by `delta` semitones
   * and mark the issue 修正済み (a correction IS a resolution).
   */
  adjustPitch(issueId: string, delta: number): ReviewEdit | null {
    const issue = this.doc.reviewIssues().find((i) => i.id === issueId);
    if (!issue || issue.canonicalNoteIds.length === 0 || delta === 0) {
      return null;
    }
    const noteChanges: ReviewNoteChange[] = issue.canonicalNoteIds.map(
      (canonicalId) => {
        const prev = editOf(this.doc, canonicalId);
        const next: ScoreNoteEdit = {
          ...prev,
          pitchDelta: prev.pitchDelta + delta,
        };
        return { canonicalId, prev, next };
      },
    );
    return this.apply({
      issueId,
      prevStatus: issue.status,
      nextStatus: "fixed",
      noteChanges,
    });
  }

  /**
   * 削除/復元: toggle the deleted flag on the issue's canonical notes.
   * Deleting counts as a correction (→ fixed); restoring reopens the issue
   * so the passage is checked again.
   */
  setNoteDeleted(issueId: string, deleted: boolean): ReviewEdit | null {
    const issue = this.doc.reviewIssues().find((i) => i.id === issueId);
    if (!issue || issue.canonicalNoteIds.length === 0) return null;
    const noteChanges: ReviewNoteChange[] = [];
    for (const canonicalId of issue.canonicalNoteIds) {
      const prev = editOf(this.doc, canonicalId);
      if (prev.deleted === deleted) continue;
      noteChanges.push({ canonicalId, prev, next: { ...prev, deleted } });
    }
    const nextStatus: ReviewIssueStatus = deleted ? "fixed" : "open";
    // No-op guard: notes already in the target state AND the status too.
    if (noteChanges.length === 0 && issue.status === nextStatus) return null;
    return this.apply({
      issueId,
      prevStatus: issue.status,
      nextStatus,
      noteChanges,
    });
  }

  /** Reopen an issue without touching note edits (revert a decision). */
  reopen(issueId: string): ReviewEdit | null {
    return this.decide(issueId, "open");
  }

  /** #114 (spec 13): edit a canonical note directly, outside any review
   *  issue - pitch shift, delete/restore and enharmonic respell share
   *  the same undo stack as review corrections. `patch` is applied on
   *  top of the note's current edit; returns null on a no-op. */
  editNote(
    canonicalId: string,
    patch: Partial<ScoreNoteEdit>,
  ): ReviewEdit | null {
    const prev = editOf(this.doc, canonicalId);
    const next: ScoreNoteEdit = { ...prev, ...patch };
    if (
      next.pitchDelta === prev.pitchDelta &&
      next.deleted === prev.deleted &&
      (next.enharmonic ?? false) === (prev.enharmonic ?? false)
    ) {
      return null;
    }
    const edit: ReviewEdit = {
      issueId: null,
      prevStatus: null,
      nextStatus: null,
      noteChanges: [{ canonicalId, prev, next }],
    };
    this.doc.setNoteEdit(canonicalId, next);
    this.push(edit);
    return edit;
  }

  /** Undo the most recent review action. Returns it, or null when the
   *  stack is empty. */
  undo(): ReviewEdit | null {
    const edit = this.undoStack.pop();
    if (!edit) return null;
    this.applyInverse(edit);
    this.redoStack.push(edit);
    return edit;
  }

  /** Redo the most recently undone action. */
  redo(): ReviewEdit | null {
    const edit = this.redoStack.pop();
    if (!edit) return null;
    this.applyForward(edit);
    this.undoStack.push(edit);
    return edit;
  }

  /* ------------------------- internals ------------------------- */

  private push(edit: ReviewEdit): void {
    this.undoStack.push(edit);
    this.redoStack.length = 0; // a new action invalidates the redo tail
  }

  private apply(edit: ReviewEdit): ReviewEdit {
    for (const change of edit.noteChanges) {
      this.doc.setNoteEdit(change.canonicalId, change.next);
    }
    if (edit.issueId != null && edit.nextStatus != null) {
      this.doc.recordReviewDecision(edit.issueId, edit.nextStatus);
    }
    this.push(edit);
    return edit;
  }

  private applyInverse(edit: ReviewEdit): void {
    // Restore note edits first, then the status - a consumer that
    // re-renders once sees a consistent state either way.
    for (const change of edit.noteChanges) {
      this.doc.setNoteEdit(change.canonicalId, change.prev);
    }
    if (edit.issueId != null && edit.prevStatus != null) {
      this.doc.recordReviewDecision(edit.issueId, edit.prevStatus);
    }
  }

  private applyForward(edit: ReviewEdit): void {
    for (const change of edit.noteChanges) {
      this.doc.setNoteEdit(change.canonicalId, change.next);
    }
    if (edit.issueId != null && edit.nextStatus != null) {
      this.doc.recordReviewDecision(edit.issueId, edit.nextStatus);
    }
  }
}

// @vitest-environment jsdom
/**
 * Score note-edit transform tests (UI-050): semitone pitch shifts and
 * delete/restore applied to canonical `sn-*` notes in MusicXML.
 */
import { describe, expect, it } from "vitest";
import concertXml from "./fixtures/score_concert.musicxml?raw";
import {
  applyNoteEdits,
  enharmonicRespell,
  isEmptyNoteEdit,
  NO_NOTE_EDIT,
  shiftPitch,
  type ScoreNoteEdit,
} from "./scoreEdits";

const parse = (xml: string) =>
  new DOMParser().parseFromString(xml, "application/xml");

function noteXml(xml: string, hsId: string): Element | null {
  return parse(xml).querySelector(`note[id="${hsId}"]`);
}

describe("shiftPitch spelling", () => {
  it("ascending shifts respell with sharps", () => {
    expect(shiftPitch("C", 0, 4, 1)).toEqual({ step: "C", alter: 1, octave: 4 });
    expect(shiftPitch("F", 0, 4, 1)).toEqual({ step: "F", alter: 1, octave: 4 });
    expect(shiftPitch("B", 0, 4, 1)).toEqual({ step: "C", alter: 0, octave: 5 });
  });

  it("descending shifts respell with flats", () => {
    expect(shiftPitch("D", 0, 4, -1)).toEqual({ step: "D", alter: -1, octave: 4 });
    expect(shiftPitch("C", 0, 4, -1)).toEqual({ step: "B", alter: 0, octave: 3 });
    expect(shiftPitch("A", 0, 4, -2)).toEqual({ step: "G", alter: 0, octave: 4 });
  });

  it("natural neighbours never produce E#/Fb spellings", () => {
    expect(shiftPitch("E", 0, 4, 1)).toEqual({ step: "F", alter: 0, octave: 4 });
    expect(shiftPitch("F", 0, 4, -1)).toEqual({ step: "E", alter: 0, octave: 4 });
  });

  it("delta 0 is a no-op", () => {
    expect(shiftPitch("G", 0, 4, 0)).toBeNull();
    expect(isEmptyNoteEdit(NO_NOTE_EDIT)).toBe(true);
  });
});

describe("applyNoteEdits", () => {
  it("returns the original string when no edits apply", () => {
    expect(applyNoteEdits(concertXml, new Map())).toBe(concertXml);
    const foreign = new Map<string, ScoreNoteEdit>([
      ["sn-999999", { pitchDelta: 1, deleted: false }],
    ]);
    expect(applyNoteEdits(concertXml, foreign)).toBe(concertXml);
  });

  it("shifts a canonical note's pitch by semitones", () => {
    // Fixture sn-000012 is B♭3 (B, alter -1, octave 3) → +1 = B natural 3.
    const before = noteXml(concertXml, "hs-sn-000012")!;
    expect(before.querySelector("pitch step")!.textContent).toBe("B");
    expect(before.querySelector("pitch alter")!.textContent).toBe("-1");
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000012", { pitchDelta: 1, deleted: false }],
    ]);
    const after = applyNoteEdits(concertXml, edits);
    expect(after).not.toBe(concertXml);
    const note = noteXml(after, "hs-sn-000012")!;
    expect(note.querySelector("pitch step")!.textContent).toBe("B");
    // alter 0 is omitted from MusicXML rather than written as "0".
    expect(note.querySelector("pitch alter")).toBeNull();
    expect(note.querySelector("pitch octave")!.textContent).toBe("3");
    // The accidental element mirrors the respelling (B♭ → B natural has
    // no accidental mark; Verovio re-derives courtesy accidentals).
    expect(note.querySelector("accidental")).toBeNull();
  });

  it("delete renders the note as a same-id rest (timing preserved)", () => {
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000012", { pitchDelta: 0, deleted: true }],
    ]);
    const after = applyNoteEdits(concertXml, edits);
    const note = noteXml(after, "hs-sn-000012")!;
    expect(note.querySelector("rest")).not.toBeNull();
    expect(note.querySelector("pitch")).toBeNull();
    // Duration survives — the measure's beat math is untouched.
    expect(note.querySelector("duration")).not.toBeNull();
  });

  it("restore removes the edit so the original notation returns", () => {
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000012", { pitchDelta: 0, deleted: true }],
    ]);
    const deleted = applyNoteEdits(concertXml, edits);
    edits.set("sn-000012", NO_NOTE_EDIT);
    // An identity edit maps back to the untouched document.
    expect(applyNoteEdits(concertXml, new Map())).toBe(concertXml);
    expect(deleted).not.toBe(concertXml);
  });

  it("enharmonic respells the same sounding pitch (#114)", () => {
    // sn-000012 is Bb3 -> respelled as A#3 (same MIDI 58).
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000012", { pitchDelta: 0, deleted: false, enharmonic: true }],
    ]);
    const after = applyNoteEdits(concertXml, edits);
    const note = noteXml(after, "hs-sn-000012")!;
    expect(note.querySelector("pitch step")!.textContent).toBe("A");
    expect(note.querySelector("pitch alter")!.textContent).toBe("1");
    expect(note.querySelector("pitch octave")!.textContent).toBe("3");
    expect(note.querySelector("accidental")!.textContent).toBe("sharp");
  });

  it("enharmonic applies after a pitch shift", () => {
    // Bb3 +3 semitones = C#4 (shift respells sharp-side); respelled
    // -> Db4 (same MIDI 61).
    const edits = new Map<string, ScoreNoteEdit>([
      ["sn-000012", { pitchDelta: 3, deleted: false, enharmonic: true }],
    ]);
    const after = applyNoteEdits(concertXml, edits);
    const note = noteXml(after, "hs-sn-000012")!;
    expect(note.querySelector("pitch step")!.textContent).toBe("D");
    expect(note.querySelector("pitch alter")!.textContent).toBe("-1");
    expect(note.querySelector("pitch octave")!.textContent).toBe("4");
  });
});

describe("enharmonicRespell", () => {
  it("flips sharp/flat families keeping the same pitch class", () => {
    expect(enharmonicRespell("C", 1, 4)).toEqual({
      step: "D",
      alter: -1,
      octave: 4,
    });
    expect(enharmonicRespell("B", -1, 3)).toEqual({
      step: "A",
      alter: 1,
      octave: 3,
    });
  });

  it("keeps the sounding octave across boundary spellings", () => {
    // B#3 (MIDI 60) -> C4; Cb4 (MIDI 59) -> B3.
    expect(enharmonicRespell("B", 1, 3)).toEqual({
      step: "C",
      alter: 0,
      octave: 4,
    });
    expect(enharmonicRespell("C", -1, 4)).toEqual({
      step: "B",
      alter: 0,
      octave: 3,
    });
  });

  it("returns null when the other family is the same spelling", () => {
    // Naturals have no single-accidental partner (E#/Cb spellings are
    // deliberately not produced), so respell is a no-op there.
    expect(enharmonicRespell("F", 0, 4)).toBeNull();
    expect(enharmonicRespell("C", 0, 4)).toBeNull();
  });
});

/**
 * Score note edits (UI-050, GUI_UX_SPEC §13 簡易音符修正).
 *
 * The review workspace's correction set is deliberately narrow: semitone
 * pitch shift and delete/restore. Edits are expressed against canonical
 * `sn-*` note ids and applied to the document's MusicXML by
 * `applyNoteEdits` — the same transform runs on the concert and F管
 * presentations (identical `hs-sn-*` ids), so both views stay consistent
 * and any consumer of `musicXml()` sees the corrected document.
 *
 * Spelling policy: ascending shifts respell with sharps, descending with
 * flats — deterministic and direction-aware, matching the P4 prototype's
 * convention. Enharmonic re-spelling that keeps pitch is a separate spec
 * item and not part of this transform.
 */
import { canonicalNoteIdFromMusicxml } from "./ids";

/** One canonical note's user edit - cumulative, never incremental state. */
export interface ScoreNoteEdit {
  /** Semitone offset vs. the document's emitted pitch (0 = unchanged). */
  readonly pitchDelta: number;
  /** User deleted this note - rendered as a rest so measure timing stays
   *  intact (a removal would shift every later onset). */
  readonly deleted: boolean;
  /** #114 (spec 13): enharmonic respell toggle - the sounding pitch is
   *  unchanged; the written spelling flips to the other accidental
   *  family (sharp <-> flat). Applied after pitchDelta. */
  readonly enharmonic?: boolean;
}

/** The identity edit - absence of a map entry means the same thing. */
export const NO_NOTE_EDIT: ScoreNoteEdit = {
  pitchDelta: 0,
  deleted: false,
  enharmonic: false,
};

export function isEmptyNoteEdit(edit: ScoreNoteEdit): boolean {
  return (
    edit.pitchDelta === 0 && !edit.deleted && !(edit.enharmonic ?? false)
  );
}

const STEP_PC: Record<string, number> = {
  C: 0,
  D: 2,
  E: 4,
  F: 5,
  G: 7,
  A: 9,
  B: 11,
};

/** pitch class → [step, alter] spellings. Ascending shifts use sharps,
 *  descending use flats (so E+1 = F, D-1 = D♭ — never E♯/F♭ here). */
const SPELL_SHARP: ReadonlyArray<readonly [string, number]> = [
  ["C", 0],
  ["C", 1],
  ["D", 0],
  ["D", 1],
  ["E", 0],
  ["F", 0],
  ["F", 1],
  ["G", 0],
  ["G", 1],
  ["A", 0],
  ["A", 1],
  ["B", 0],
];
const SPELL_FLAT: ReadonlyArray<readonly [string, number]> = [
  ["C", 0],
  ["D", -1],
  ["D", 0],
  ["E", -1],
  ["E", 0],
  ["F", 0],
  ["G", -1],
  ["G", 0],
  ["A", -1],
  ["A", 0],
  ["B", -1],
  ["B", 0],
];

const ACCIDENTAL_NAME: Record<number, string> = {
  "-2": "flat-flat",
  "-1": "flat",
  "1": "sharp",
  "2": "double-sharp",
};

/**
 * Shift a spelled pitch by `delta` semitones and return the new
 * (step, alter, octave) spelling. Returns null for unspellable input.
 */
export function shiftPitch(
  step: string,
  alter: number,
  octave: number,
  delta: number,
): { step: string; alter: number; octave: number } | null {
  const pc0 = STEP_PC[step];
  if (pc0 === undefined || delta === 0) return null;
  const midi = (octave + 1) * 12 + pc0 + alter + delta;
  const pc = ((midi % 12) + 12) % 12;
  const [s, a] = (delta > 0 ? SPELL_SHARP : SPELL_FLAT)[pc];
  return { step: s, alter: a, octave: Math.floor(midi / 12) - 1 };
}

/** #114 (spec 13 異名同音): respell the SAME sounding pitch in the other
 *  accidental family (sharp <-> flat). Prefers a single accidental; when
 *  both candidates need a double accidental the flat family wins (B# ->
 *  C keeps naturals stable). Returns null for unspellable input. */
export function enharmonicRespell(
  step: string,
  alter: number,
  octave: number,
): { step: string; alter: number; octave: number } | null {
  const pc0 = STEP_PC[step];
  if (pc0 === undefined) return null;
  const midi = (octave + 1) * 12 + pc0 + alter;
  const pc = ((midi % 12) + 12) % 12;
  const sharp = SPELL_SHARP[pc];
  const flat = SPELL_FLAT[pc];
  const currentIsFlat = alter < 0;
  const [first, second] = currentIsFlat ? [sharp, flat] : [flat, sharp];
  const pick = Math.abs(first[1]) <= 1 ? first : second;
  // No-op guard: the other family is the same spelling (naturals).
  if (pick[0] === step && pick[1] === alter) return null;
  // STEP_PC+alter can leave [0,11] (B#=12, Cb=-1), so solve the octave
  // from midi - (step+alter) instead of midi/12.
  return {
    step: pick[0],
    alter: pick[1],
    octave: Math.floor((midi - (STEP_PC[pick[0]] + pick[1])) / 12) - 1,
  };
}

function setChildText(
  parent: Element,
  doc: XMLDocument,
  tag: string,
  text: string | null,
  before?: Element | null,
): void {
  const existing = parent.querySelector(`:scope > ${tag}`);
  if (text === null) {
    existing?.remove();
    return;
  }
  if (existing) {
    existing.textContent = text;
    return;
  }
  const el = doc.createElement(tag);
  el.textContent = text;
  parent.insertBefore(el, before ?? null);
}

/** Write a (step, alter, octave) spelling back into <pitch> and sync the
 *  <accidental> element so the rendered glyph matches. */
function writeSpelling(
  noteEl: Element,
  pitch: Element,
  doc: XMLDocument,
  next: { step: string; alter: number; octave: number },
): void {
  const octaveEl = pitch.querySelector("octave");
  setChildText(pitch, doc, "step", next.step, pitch.querySelector("alter") ?? octaveEl);
  setChildText(
    pitch,
    doc,
    "alter",
    next.alter === 0 ? null : String(next.alter),
    octaveEl,
  );
  setChildText(pitch, doc, "octave", String(next.octave));
  const acc = noteEl.querySelector(":scope > accidental");
  const accName = ACCIDENTAL_NAME[next.alter];
  if (accName === undefined) acc?.remove();
  else if (acc) acc.textContent = accName;
  else {
    const el = doc.createElement("accidental");
    el.textContent = accName;
    noteEl.appendChild(el);
  }
}

/** Read the note's current (step, alter, octave), or null for rests /
 *  unspellable pitches. */
function readSpelling(
  noteEl: Element,
): { step: string; alter: number; octave: number } | null {
  const pitch = noteEl.querySelector(":scope > pitch");
  if (!pitch) return null; // already a rest - nothing to transpose
  const step = pitch.querySelector("step")?.textContent ?? "";
  const alterText = pitch.querySelector("alter")?.textContent;
  const octaveText = pitch.querySelector("octave")?.textContent;
  const octave = octaveText != null ? Number(octaveText) : NaN;
  if (!Number.isFinite(octave) || !(step in STEP_PC)) return null;
  return { step, alter: alterText != null ? Number(alterText) : 0, octave };
}

/** Rewrite a <note>'s <pitch>/<alter>/<octave> and its <accidental> text
 *  so the rendered glyph matches the shifted sounding pitch. */
function shiftNotePitch(noteEl: Element, doc: XMLDocument, delta: number): void {
  const cur = readSpelling(noteEl);
  if (!cur) return;
  const next = shiftPitch(cur.step, cur.alter, cur.octave, delta);
  if (!next) return;
  writeSpelling(noteEl, noteEl.querySelector(":scope > pitch")!, doc, next);
}

/** #114: enharmonic respell - same sounding pitch, other accidental
 *  family (spec 13). */
function respellNotePitch(noteEl: Element, doc: XMLDocument): void {
  const cur = readSpelling(noteEl);
  if (!cur) return;
  const next = enharmonicRespell(cur.step, cur.alter, cur.octave);
  if (!next) return;
  writeSpelling(noteEl, noteEl.querySelector(":scope > pitch")!, doc, next);
}

/** Convert a pitched <note> into a same-duration rest, keeping the
 *  `hs-sn-*` id so canonical identity (selection, issue links) survives.
 *  Ties/notations/beams that only make sense for a pitch are dropped. */
function noteToRest(noteEl: Element, doc: XMLDocument): void {
  const pitch = noteEl.querySelector(":scope > pitch");
  if (!pitch) return; // already a rest
  const rest = doc.createElement("rest");
  noteEl.replaceChild(rest, pitch);
  for (const tag of ["accidental", "tie", "notations", "stem", "beam"] as const) {
    for (const el of Array.from(noteEl.querySelectorAll(`:scope > ${tag}`))) {
      el.remove();
    }
  }
}

/**
 * Apply canonical-note edits to a MusicXML document and return the new
 * XML string. Unedited input short-circuits to the original string so the
 * render path can tell "no change" apart cheaply.
 */
export function applyNoteEdits(
  xml: string,
  edits: ReadonlyMap<string, ScoreNoteEdit>,
): string {
  if (edits.size === 0) return xml;
  const doc = new DOMParser().parseFromString(xml, "application/xml");
  if (doc.querySelector("parsererror")) {
    throw new Error("MusicXML parse failed");
  }
  let changed = false;
  for (const noteEl of Array.from(doc.querySelectorAll("note[id]"))) {
    const canonical = canonicalNoteIdFromMusicxml(noteEl.getAttribute("id") ?? "");
    if (!canonical) continue;
    const edit = edits.get(canonical);
    if (!edit) continue;
    if (edit.deleted) {
      noteToRest(noteEl, doc);
      changed = true;
    } else {
      // pitchDelta first, then the enharmonic respell of the shifted
      // pitch (edit semantics: respell applies to the edited spelling).
      if (edit.pitchDelta !== 0) {
        shiftNotePitch(noteEl, doc, edit.pitchDelta);
        changed = true;
      }
      if (edit.enharmonic) {
        respellNotePitch(noteEl, doc);
        changed = true;
      }
    }
  }
  return changed ? new XMLSerializer().serializeToString(doc) : xml;
}
